/* pele diagrams follow the VitePress theme in light and dark mode; the shared look comes from
   @yolo-twice/pele-markdown/theme.css (imported in index.ts). */
.pele {
  --pele-bg: var(--vp-c-bg);
  --pele-fg: var(--vp-c-text-1);
  --pele-muted: var(--vp-c-text-2);
  --pele-line: var(--vp-c-text-2);
  --pele-surface: var(--vp-c-bg-soft);
  --pele-surface-alt: var(--vp-c-bg-alt);
  --pele-border: var(--vp-c-divider);
  --pele-font: var(--vp-font-family-base);
  --yt-pele-outline: #6f3fd0; /* light mode: deep purple, readable on cream */
}
.dark .pele {
  --yt-pele-outline: #c39bff;
}
div.pele {
  margin: 1.75rem 0;
  overflow-x: auto;
}
.pele-error {
  border: 1px solid var(--vp-c-danger-1);
  padding: 1rem;
  white-space: pre-wrap;
}
.status-banner {
  border-left: 4px solid var(--vp-c-warning-1);
  background: var(--vp-c-warning-soft);
  padding: 0.75rem 1rem;
  border-radius: 6px;
  margin: 1rem 0 2rem;
}

/* ---------- brand: from the wordmark (navy to purple, cream, orange), matches the deck ---------- */
:root {
  --vp-font-family-base: Inter, ui-sans-serif, system-ui, sans-serif;
  --brand-heading: Nunito, Inter, ui-sans-serif, system-ui, sans-serif;

  /* light mode: cream paper, navy ink, a darker orange that keeps contrast */
  --vp-c-bg: #fbf7ef;
  --vp-c-bg-alt: #f4eee2;
  --vp-c-bg-soft: #f1eadc;
  --vp-c-text-1: #101648;
  --vp-c-text-2: #3d4270;
  --vp-c-brand-1: #c2410c;
  --vp-c-brand-2: #a8380a;
  --vp-c-brand-3: #c2410c;
  --vp-c-brand-soft: rgb(194 65 12 / 0.12);
  --vp-~-name-color: var(--vp-c-brand-1);
}

.dark {
  --vp-c-bg: #070a2a;
  --vp-c-bg-alt: #04061c;
  --vp-c-bg-soft: #11163f;
  --vp-c-bg-elv: #11163f;
  --vp-c-divider: #262c5e;
  --vp-c-border: #262c5e;
  --vp-c-gutter: #04061c;
  --vp-c-text-1: #f8f1e4;
  --vp-c-text-2: #d8d3e6;
  --vp-c-text-3: #9291b8;

  --vp-c-brand-1: #fd7a2e;
  --vp-c-brand-2: #ff9a5c;
  --vp-c-brand-3: #fd5f02;
  --vp-c-brand-soft: rgb(253 95 2 / 0.16);

  --vp-code-block-bg: #04061c;
  --vp-code-bg: #11163f;
}

/* headings in the wordmark's rounded heavy style */
.VPHero .name, .VPHero .text, .vp-doc h1, .vp-doc h2, .VPFeature .title {
  font-family: var(--brand-heading);
  font-weight: 900;
  letter-spacing: -0.01em;
}
.vp-doc h2 { font-weight: 800; }

/* brand button: navy text on orange */
.VPButton.brand { color: #070a2a; background-color: #fd5f02; border-color: #fd5f02; }
.VPButton.brand:hover { color: #070a2a; background-color: #ff7a2a; border-color: #ff7a2a; }

/* dark background: the wordmark's navy and purple glows */
.dark .VPHome, .dark .VPContent {
  background:
    radial-gradient(900px 520px at 0% 0%, rgb(22 44 150 / 0.35), transparent 62%),
    radial-gradient(900px 600px at 100% 30%, rgb(76 16 150 / 0.28), transparent 62%);
}

/* hero image: the wordmark as a poster */
.VPHero .image-container { transform: none; }
.VPHero .image-bg { display: none; }
.VPHero .image-src {
  position: static; transform: none;
  max-width: 100%; width: 520px; border-radius: 16px;
  box-shadow: 0 24px 60px rgb(4 6 28 / 0.55);
}

/* nav logo */
.VPNavBarTitle .logo { height: 30px; }

/* feature cards: the deck's tagged colours, one per question */
.VPFeatures .item:nth-child(1) .VPFeature { border-top: 3px solid #6cb6ff; }
.VPFeatures .item:nth-child(2) .VPFeature { border-top: 3px solid #c39bff; }
.VPFeatures .item:nth-child(3) .VPFeature { border-top: 3px solid #e3b341; }
.VPFeatures .item:nth-child(4) .VPFeature { border-top: 3px solid #4ac26b; }

/* VitePress paints solid "curtains" under the aside and sidebar; let the gradient show through */
.dark .VPDoc .aside-curtain { display: none; }
.VPButton.brand, .VPButton.brand:hover { color: #070a2a !important; }
